insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0001-0000-4000-8000-000000000015', 'en', null, 'Algebra: Foundations', 'Algebra is the branch of mathematics that uses letters to stand for numbers, turning arithmetic into a language for stating and solving general problems. This course builds the foundations - variables and expressions, linear equations and inequalities, graphing, systems, polynomials, factoring, and the quadratic formula - with worked examples and practice at every step. Structure and scope adapted from the article ''Algebra'' on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 21, true, 'math', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0001-0000-4000-8000-000000000015', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"In algebra, a letter such as x is used to...","options":["stand for an unknown or varying number","always mean the number 10","signal that you must multiply","represent only negative numbers"],"answer":0,"explanation":"A variable is a symbol that holds a number we do not yet know or that can change - that is the whole point of algebra."},{"prompt":"Using the order of operations, 2 + 3 * 4 equals...","options":["20","14","24","9"],"answer":1,"explanation":"Multiplication comes before addition: 3 * 4 = 12, then 2 + 12 = 14."},{"prompt":"Simplified by combining like terms, 3x + 5x equals...","options":["8x","15x","8x^2","35x"],"answer":0,"explanation":"Like terms add their coefficients: 3 + 5 = 8, keeping the same variable x."},{"prompt":"Solving 2x + 3 = 11 gives x =","options":["7","4","5.5","8"],"answer":1,"explanation":"Subtract 3 to get 2x = 8, then divide by 2 to get x = 4."},{"prompt":"If -2x > 6, then...","options":["x > -3","x < -3","x > 3","x < 3"],"answer":1,"explanation":"Dividing by a negative number flips the inequality: x < -3."},{"prompt":"The line y = 2x + 1 has slope...","options":["1","2","-2","0"],"answer":1,"explanation":"In y = mx + b the slope is m, so here the slope is 2 and the y-intercept is 1."},{"prompt":"Expanded, (x + 3)^2 equals...","options":["x^2 + 9","x^2 + 6x + 9","x^2 + 3x + 9","x^2 + 6x + 3"],"answer":1,"explanation":"(x + 3)(x + 3) = x^2 + 3x + 3x + 9 = x^2 + 6x + 9; the middle term is easy to forget."}]}'::jsonb, null, 10),
  (2, 'Variables, expressions, and the order of operations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Read a letter as a stand-in for a number, write a real situation as an algebraic expression, and evaluate expressions using the correct order of operations. Warm-up: if one ticket costs d dollars, what single expression gives the cost of 4 tickets?"},{"heading":"The idea","text":"Algebra extends arithmetic by letting a letter, called a variable, stand for a number we do not yet know or that is allowed to change. An expression such as 3x + 5 is a recipe: multiply the value of x by 3, then add 5. Variables matter because one expression captures infinitely many cases at once - 3x + 5 describes a result for every possible value of x, not just one. To get a single number out of an expression you substitute a value for the variable and simplify. When an expression mixes operations, the order of operations settles which to do first: Parentheses, then Exponents, then Multiplication and Division from left to right, then Addition and Subtraction from left to right. A common memory aid is PEMDAS. Without a shared rule, 2 + 3 * 4 could be read as 20 or as 14; the convention fixes the answer at 14, because multiplication is done before addition."},{"heading":"Worked examples","text":"Evaluate 3x + 5 when x = 4: 3 * 4 + 5 = 12 + 5 = 17. Evaluate 2 + 3 * 4: do the multiplication first, 3 * 4 = 12, then 2 + 12 = 14. Evaluate (2 + 3) * 4: parentheses first, 5 * 4 = 20 - the parentheses change the result. Evaluate 10 - 2^3 / 4: exponent first, 2^3 = 8; then 8 / 4 = 2; then 10 - 2 = 8. Turn words into symbols: ''5 more than twice n'' is 2n + 5, and at n = 6 that is 2 * 6 + 5 = 17. Evaluate 4 + 6 / 2 * 3: division and multiplication run left to right, so 6 / 2 = 3, then 3 * 3 = 9, then 4 + 9 = 13."},{"heading":"Your turn","text":"1) Evaluate 5x - 2 when x = 3. 2) Evaluate 7 + 2 * 5. 3) Evaluate (7 + 2) * 5. 4) Write ''three less than a number k'' as an expression. 5) Evaluate 12 / 2^2 + 1. 6) Evaluate 2 * (3 + 4)^2. Answers: 1) 5 * 3 - 2 = 15 - 2 = 13. 2) 7 + 10 = 17. 3) 9 * 5 = 45. 4) k - 3. 5) 2^2 = 4, then 12 / 4 = 3, then 3 + 1 = 4. 6) 3 + 4 = 7, 7^2 = 49, 2 * 49 = 98."},{"heading":"Common mistakes & exit ticket","text":"Mistake: working strictly left to right and reading 2 + 3 * 4 as 20 - multiplication comes first, so the value is 14. Mistake: treating 3x as ''the digits 3 then x'' rather than 3 times x. Mistake: dropping parentheses, which can silently change an answer. Exit: (a) Evaluate 6 + 4 / 2. (b) Write ''double a number, then add 7'' as an expression. Answers: 4 / 2 = 2, then 6 + 2 = 8; the expression is 2x + 7."}]}'::jsonb, 'Writing 3x always means 3 times x; a number placed next to a variable implies multiplication.', 12),
  (3, 'Like terms, the distributive property, and solving equations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Simplify an expression by combining like terms and using the distributive property, then solve one- and two-step linear equations. Warm-up: are 4x and 4x^2 like terms, and why or why not?"},{"heading":"The idea","text":"Like terms have exactly the same variable part, so 3x and 5x are like terms, but 3x and 3x^2 are not. You combine like terms by adding their coefficients: 3x + 5x = 8x. The distributive property says a(b + c) = ab + ac, so multiplication spreads across a sum: 2(x + 4) = 2x + 8. Together these let you tidy an expression before you solve it. An equation states that two expressions are equal, and solving it means finding the value of the variable that makes the statement true. The guiding principle is balance: whatever operation you apply to one side you must apply to the other. To undo an addition you subtract; to undo a multiplication you divide. A one-step equation needs a single such move, while a two-step equation such as 2x + 3 = 11 needs two - first undo the addition, then undo the multiplication."},{"heading":"Worked examples","text":"Combine like terms: 7a - 2a + 5 = 5a + 5. Distribute: 3(x + 4) = 3x + 12. Simplify fully: 2(x + 3) + 4x = 2x + 6 + 4x = 6x + 6. Solve one step: x + 7 = 12, subtract 7 from both sides, x = 5. Solve one step: 4x = 20, divide both sides by 4, x = 5. Solve two steps: 2x + 3 = 11. Subtract 3 to get 2x = 8, then divide by 2 to get x = 4. Check by substituting back: 2 * 4 + 3 = 11, which is true. Solve with distribution: 3(x - 1) = 12. Dividing both sides by 3 gives x - 1 = 4, so x = 5."},{"heading":"Your turn","text":"1) Combine: 6y + 2y - 3y. 2) Distribute: 5(2x + 1). 3) Simplify: 4(x + 2) - 3x. 4) Solve: x - 6 = 10. 5) Solve: 3x = 21. 6) Solve: 5x - 4 = 16. Answers: 1) 5y. 2) 10x + 5. 3) 4x + 8 - 3x = x + 8. 4) x = 16. 5) x = 7. 6) add 4 to get 5x = 20, then divide by 5 to get x = 4."},{"heading":"Common mistakes & exit ticket","text":"Mistake: combining unlike terms, such as adding an x term to a plain number. Mistake: distributing to only the first term inside the parentheses, writing 2(x + 4) = 2x + 4 instead of 2x + 8. Mistake: changing only one side of an equation and breaking the balance. Exit: (a) Simplify 3(x + 2) + x. (b) Solve 4x - 5 = 7. Answers: 3x + 6 + x = 4x + 6; add 5 to get 4x = 12, then divide by 4 to get x = 3."}]}'::jsonb, 'Keep an equation balanced: whatever you do to one side, do the exact same thing to the other side.', 14),
  (4, 'Solving inequalities', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Solve linear inequalities, apply the sign-flip rule correctly, and describe the solution as a range of values. Warm-up: is x = 5 a solution of x + 2 > 6?"},{"heading":"The idea","text":"An inequality compares two expressions with <, >, <=, or >=, and its solution is usually a whole range of numbers rather than a single value. You solve an inequality almost exactly as you solve an equation: add, subtract, multiply, and divide to isolate the variable, keeping both sides balanced. There is one crucial extra rule: when you multiply or divide both sides by a negative number, you must flip the direction of the inequality sign. For instance, -2x > 6 becomes x < -3 after dividing by -2. This happens because multiplying by a negative reverses order on the number line - if a < b, then -a > -b. The symbols < and > are strict, meaning the endpoint itself is excluded, while <= and >= include the endpoint. A solution such as x <= 4 covers 4 and every number below it."},{"heading":"Worked examples","text":"Solve x + 3 <= 7: subtract 3 to get x <= 4. Solve 2x > 10: divide by 2 to get x > 5. Solve -3x < 12: divide by -3 and flip the sign to get x > -4. Solve 5 - x >= 2: subtract 5 to get -x >= -3, then multiply by -1 and flip to get x <= 3. Solve 2x + 1 < 9: subtract 1 to get 2x < 8, then divide by 2 to get x < 4. Check a boundary for x < 4: test x = 0, giving 1 < 9, true; test x = 5, giving 11 < 9, false - so values below 4 work, exactly as the solution claims."},{"heading":"Your turn","text":"1) Solve x - 2 > 5. 2) Solve 4x <= 20. 3) Solve -x < 3. 4) Solve -2x >= 8. 5) Solve 3x + 2 <= 14. 6) Is x = 1 a solution of 2x - 1 < 4? Answers: 1) x > 7. 2) x <= 5. 3) multiply by -1 and flip to get x > -3. 4) divide by -2 and flip to get x <= -4. 5) subtract 2 to get 3x <= 12, then divide by 3 to get x <= 4. 6) 2 * 1 - 1 = 1, and 1 < 4, so yes."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting to flip the sign when multiplying or dividing by a negative number - the single most common inequality error. Mistake: flipping the sign when only adding or subtracting, which never requires a flip. Mistake: reporting one number instead of a range. Exit: (a) Solve -4x > 20. (b) Solve x + 5 >= 1. Answers: divide by -4 and flip to get x < -5; subtract 5 to get x >= -4."}]}'::jsonb, 'The one extra rule beyond equations: multiplying or dividing both sides by a negative number flips the inequality sign.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Evaluate 4 + 2 * 5 using the order of operations.","options":["30","14","20","11"],"answer":1,"explanation":"Multiplication first: 2 * 5 = 10, then 4 + 10 = 14."},{"prompt":"Simplify 3(x + 4) with the distributive property.","options":["3x + 4","3x + 12","x + 12","3x + 7"],"answer":1,"explanation":"Distribute the 3 to both terms: 3 * x + 3 * 4 = 3x + 12."},{"prompt":"Combine like terms: 7a - 2a + 5.","options":["5a + 5","9a + 5","5a - 5","10a"],"answer":0,"explanation":"7a - 2a = 5a, and the 5 has no like term, so the result is 5a + 5."},{"prompt":"Solve 5x - 4 = 16.","options":["x = 4","x = 2.4","x = 20","x = 3"],"answer":0,"explanation":"Add 4 to get 5x = 20, then divide by 5 to get x = 4."},{"prompt":"Solve the inequality x + 3 <= 7.","options":["x <= 4","x >= 4","x <= 10","x <= -4"],"answer":0,"explanation":"Subtract 3 from both sides to get x <= 4; no sign flip is needed."},{"prompt":"When you multiply or divide both sides of an inequality by a negative number, you must...","options":["flip the inequality sign","drop the sign entirely","add the two sides","square both sides"],"answer":0,"explanation":"A negative multiplier reverses order on the number line, so the inequality sign flips."}]}'::jsonb, null, 8),
  (6, 'The coordinate plane, slope, and graphing lines', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Plot points on the coordinate plane, compute the slope between two points, and graph a line written as y = mx + b. Warm-up: starting from the origin, which direction do you move to reach the point (0, 3)?"},{"heading":"The idea","text":"The coordinate plane is formed by a horizontal x-axis and a vertical y-axis that cross at the origin (0, 0). A point is written (x, y): move x units right or left, then y units up or down. A line can be written in slope-intercept form y = mx + b, where m is the slope and b is the y-intercept, the y-value where the line crosses the vertical axis. Slope measures steepness as rise over run, the change in y divided by the change in x between any two points: m = (y2 - y1) / (x2 - x1). A positive slope rises from left to right, a negative slope falls, a slope of zero is flat, and a vertical line has undefined slope. To graph y = mx + b, first plot the intercept at (0, b), then use the slope to step to a second point and draw the straight line through both."},{"heading":"Worked examples","text":"Slope through (1, 2) and (3, 8): m = (8 - 2) / (3 - 1) = 6 / 2 = 3. Graph y = 2x + 1: start at the intercept (0, 1); the slope 2 means up 2 and right 1, landing on (1, 3); connect the points. Graph y = -x + 4: intercept (0, 4); slope -1 means down 1 and right 1, landing on (1, 3). Read a line directly: y = (1/2)x - 2 has slope 1/2 and crosses the y-axis at -2. Find where y = 2x - 6 crosses the x-axis by setting y = 0: 0 = 2x - 6, so x = 3, giving the x-intercept (3, 0)."},{"heading":"Your turn","text":"1) Find the slope through (2, 1) and (6, 9). 2) Give the slope and y-intercept of y = -3x + 5. 3) Give the y-intercept of y = 4x - 7. 4) Find the slope through (0, 0) and (2, 6). 5) Where does y = x - 4 cross the x-axis? Answers: 1) (9 - 1) / (6 - 2) = 8 / 4 = 2. 2) slope -3, y-intercept 5. 3) -7, at the point (0, -7). 4) 6 / 2 = 3. 5) set y = 0 to get 0 = x - 4, so x = 4, at the point (4, 0)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: computing slope as run over rise, dividing the change in x by the change in y instead of the other way around. Mistake: subtracting the coordinates in different orders on top and bottom; keep both differences in the same order. Mistake: confusing the slope m with the intercept b. Exit: (a) Find the slope through (1, 1) and (4, 7). (b) Give the slope and y-intercept of y = 5x - 2. Answers: (7 - 1) / (4 - 1) = 6 / 3 = 2; slope 5 and y-intercept -2."}]}'::jsonb, 'In slope-intercept form y = mx + b, the letter m is always the slope and b is always the y-intercept.', 13),
  (7, 'Systems of linear equations', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Solve a system of two linear equations by substitution and by elimination, and explain what the solution means. Warm-up: geometrically, what does it mean for a pair of values to solve two linear equations at once?"},{"heading":"The idea","text":"A system of linear equations is two or more equations that must all hold at the same time. For two lines, the solution is the point (x, y) where they intersect - the single pair of values that satisfies both equations. Two reliable methods find it. In substitution, you solve one equation for one variable, then plug that expression into the other equation, leaving a single equation in one variable. In elimination, you add or subtract the equations, scaling one or both first if needed, so that one variable cancels, again leaving a single equation in one variable. Once you have one value, substitute it back to get the other. A two-line system can have exactly one solution when the lines cross, no solution when the lines are parallel and never meet, or infinitely many solutions when the two equations describe the very same line."},{"heading":"Worked examples","text":"Substitution: solve y = 2x and x + y = 6. Replace y with 2x: x + 2x = 6, so 3x = 6 and x = 2; then y = 2 * 2 = 4, giving (2, 4). Elimination: solve x + y = 7 and x - y = 1. Add the equations so y cancels: 2x = 8, x = 4; substitute into x + y = 7 to get y = 3, giving (4, 3). Elimination with subtraction: solve 2x + y = 5 and x + y = 3. Subtract the second from the first so y cancels: x = 2; then 2 + y = 3, so y = 1, giving (2, 1). Check: 2 * 2 + 1 = 5 and 2 + 1 = 3, both true."},{"heading":"Your turn","text":"1) Substitution: y = x + 1 and x + y = 9. 2) Elimination: x + y = 10 and x - y = 2. 3) Solve 2x + y = 7 and y = x + 1. 4) Solve 3x + y = 9 and x + y = 5. 5) What kind of solution do two parallel lines give? Answers: 1) x + (x + 1) = 9, so 2x = 8, x = 4, y = 5, giving (4, 5). 2) add to get 2x = 12, x = 6, y = 4, giving (6, 4). 3) 2x + (x + 1) = 7, so 3x = 6, x = 2, y = 3, giving (2, 3). 4) subtract to get 2x = 4, x = 2, y = 3, giving (2, 3). 5) none - parallel lines never intersect."},{"heading":"Common mistakes & exit ticket","text":"Mistake: finding one variable but forgetting to substitute back for the other. Mistake: adding the equations when the variable coefficients do not actually cancel; line them up and scale first so one variable disappears. Mistake: reporting a single number instead of an ordered pair. Exit: (a) Solve y = 3x and x + y = 8. (b) Solve x + y = 6 and x - y = 2. Answers: x + 3x = 8, so x = 2 and y = 6, giving (2, 6); add to get 2x = 8, so x = 4 and y = 2, giving (4, 2)."}]}'::jsonb, 'After finding one variable, always substitute it back to find the other - a system needs both values.', 13),
  (8, 'Exponents, polynomials, and factoring', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Apply the basic exponent rules, add and multiply polynomials, and factor simple quadratic expressions. Warm-up: written as a product, what does x^3 mean?"},{"heading":"The idea","text":"An exponent counts repeated multiplication, so x^3 = x * x * x. The product rule says x^a * x^b = x^(a+b), and the power rule says (x^a)^b = x^(a*b). A polynomial is a sum of terms, each a number times a whole-number power of x, such as x^2 + 3x + 2. You add polynomials by combining like terms, and you multiply them by distributing every term of one across every term of the other - for two binomials this is often called FOIL, for First, Outer, Inner, Last. Factoring reverses multiplication: you rewrite a polynomial as a product of simpler pieces. To factor x^2 + bx + c, look for two numbers that multiply to c and add to b. You can also pull out a common factor shared by every term, as in 2x + 6 = 2(x + 3). Factoring is the main tool for solving quadratic equations in the next lesson."},{"heading":"Worked examples","text":"Exponents: x^2 * x^5 = x^7, and (x^3)^2 = x^6. Add polynomials: (x^2 + 3x + 1) + (2x^2 - x + 4) = 3x^2 + 2x + 5. Multiply binomials: (x + 2)(x + 3) = x^2 + 3x + 2x + 6 = x^2 + 5x + 6. Pull out a common factor: 3x^2 + 6x = 3x(x + 2). Factor a quadratic: for x^2 + 5x + 6, find two numbers that multiply to 6 and add to 5, namely 2 and 3, so it factors as (x + 2)(x + 3). Factor a difference of squares: x^2 - 9 = (x - 3)(x + 3), since 9 = 3^2."},{"heading":"Your turn","text":"1) Simplify x^4 * x^3. 2) Simplify (x^2)^4. 3) Add (2x^2 + x) + (x^2 + 3x). 4) Multiply (x + 1)(x + 4). 5) Factor x^2 + 7x + 12. 6) Factor 5x^2 + 10x. Answers: 1) x^7. 2) x^8. 3) 3x^2 + 4x. 4) x^2 + 4x + x + 4 = x^2 + 5x + 4. 5) two numbers that multiply to 12 and add to 7 are 3 and 4, so (x + 3)(x + 4). 6) pull out 5x: 5x(x + 2)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: multiplying the exponents when you multiply same-base powers; x^2 * x^3 is x^5, not x^6. Mistake: when multiplying binomials, skipping the Outer and Inner products and writing (x + 2)(x + 3) = x^2 + 6. Mistake: forgetting to look for a common factor first. Exit: (a) Simplify x^5 * x^2. (b) Factor x^2 + 6x + 8. Answers: x^7; two numbers that multiply to 8 and add to 6 are 2 and 4, so (x + 2)(x + 4)."}]}'::jsonb, 'When you multiply powers of the same base you add the exponents: x^a * x^b = x^(a+b), not x^(a*b).', 14),
  (9, 'Quadratic equations and the quadratic formula', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Recognize a quadratic equation, solve one by factoring, and apply the quadratic formula when factoring is difficult. Warm-up: in a quadratic equation, what is the highest power of x?"},{"heading":"The idea","text":"A quadratic equation has the form ax^2 + bx + c = 0, where a is not 0; its defining feature is the squared term, so the highest power of x is 2. Many quadratics can be solved by factoring and then using the zero-product property: if a product equals 0, at least one of the factors must be 0. For example, (x - 2)(x - 3) = 0 forces x = 2 or x = 3. When a quadratic does not factor nicely, the quadratic formula always works: x = (-b +/- sqrt(b^2 - 4ac)) / (2a). The piece under the square root, b^2 - 4ac, is called the discriminant: if it is positive there are two real solutions, if it is zero there is exactly one, and if it is negative there are no real solutions. A quadratic usually has two solutions because the matching curve, a parabola, can cross the x-axis in two places."},{"heading":"Worked examples","text":"Solve by factoring: x^2 + 5x + 6 = 0 factors as (x + 2)(x + 3) = 0, so x = -2 or x = -3. Solve x^2 - 7x + 12 = 0: (x - 3)(x - 4) = 0, so x = 3 or x = 4. Use the formula on x^2 + 3x + 2 = 0 with a = 1, b = 3, c = 2: the discriminant is 3^2 - 4 * 1 * 2 = 9 - 8 = 1, so x = (-3 +/- sqrt(1)) / 2 = (-3 +/- 1) / 2, giving x = -1 or x = -2. Use the formula on x^2 - 4x + 1 = 0: the discriminant is 16 - 4 = 12, so x = (4 +/- sqrt(12)) / 2 = 2 +/- sqrt(3)."},{"heading":"Your turn","text":"1) Solve (x - 5)(x + 1) = 0. 2) Solve x^2 + 7x + 12 = 0 by factoring. 3) In 2x^2 + 3x - 5 = 0, name a, b, and c. 4) Compute the discriminant of x^2 + 2x + 1 = 0. 5) Solve x^2 - 5x + 6 = 0. 6) Use the formula on x^2 + x - 6 = 0. Answers: 1) x = 5 or x = -1. 2) (x + 3)(x + 4) = 0, so x = -3 or x = -4. 3) a = 2, b = 3, c = -5. 4) 2^2 - 4 * 1 * 1 = 0, so there is one real solution. 5) (x - 2)(x - 3) = 0, so x = 2 or x = 3. 6) discriminant 1 + 24 = 25, so x = (-1 +/- 5) / 2, giving x = 2 or x = -3."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting the +/- in the quadratic formula and reporting only one root. Mistake: sign slips with b and c; in ax^2 + bx + c, read c = -6 as negative, not positive 6. Mistake: dividing only part of the numerator by 2a instead of the whole thing. Exit: (a) Solve (x + 4)(x - 2) = 0. (b) Compute the discriminant of x^2 + 3x + 2 = 0. Answers: x = -4 or x = 2; 3^2 - 4 * 1 * 2 = 9 - 8 = 1, so there are two real solutions."}]}'::jsonb, 'The +/- in the quadratic formula produces two answers; compute both the plus case and the minus case.', 14),
  (10, 'Key terms', 'vocab', '{"items":[{"term":"variable","translation":"a letter that stands for an unknown or changing number","example":"In 3x + 5, the letter x is the variable."},{"term":"coefficient","translation":"the number multiplying a variable in a term","example":"In the term 7x, the coefficient is 7."},{"term":"expression","translation":"a combination of numbers, variables, and operations with no equals sign","example":"2x + 5 is an expression; because it has no equals sign, it is not an equation."},{"term":"linear equation","translation":"an equation whose variable appears only to the first power, graphing as a straight line","example":"2x + 3 = 11 is a linear equation with solution x = 4."},{"term":"inequality","translation":"a statement comparing two expressions with <, >, <=, or >=","example":"x + 2 > 6 is an inequality whose solution is the range x > 4."},{"term":"slope","translation":"the steepness of a line, measured as rise over run, the m in y = mx + b","example":"The line y = 2x + 1 has slope 2."},{"term":"y-intercept","translation":"the y-value where a line crosses the vertical axis, the b in y = mx + b","example":"In y = 2x + 1 the y-intercept is 1, at the point (0, 1)."},{"term":"polynomial","translation":"a sum of terms, each a number times a whole-number power of a variable","example":"x^2 + 3x + 2 is a polynomial."},{"term":"quadratic formula","translation":"x = (-b +/- sqrt(b^2 - 4ac)) / (2a), which solves any equation ax^2 + bx + c = 0","example":"The quadratic formula solves x^2 + 3x + 2 = 0 to give x = -1 or x = -2."}]}'::jsonb, null, 10)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0001-0000-4000-8000-000000000015' and l.position = v.pos
);
